R,C=19,16
g=[[4]*C for _ in range(R)]
ones=[(2,2),(4,14),(10,10),(17,9)]
sixes=[(4,4),(6,6),(7,14),(15,2)]
for r,c in ones:g[r][c]=1
for r,c in sixes:g[r][c]=6
# fill the segment between diagonal-aligned 1 points
for i,(r1,c1) in enumerate(ones):
 for r2,c2 in ones[i+1:]:
  if abs(r2-r1)==abs(c2-c1):
   dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
   for k in range(abs(r2-r1)+1):
    r,c=r1+k*dr,c1+k*dc
    if g[r][c]!=6:g[r][c]=1
# draw each 6's / diagonal fully across board
for r0,c0 in sixes:
 for r in range(R):
  c=r0+c0-r
  if 0<=c<C and g[r][c]!=1:g[r][c]=6
print('\n'.join(' '.join(map(str,row)) for row in g))
